/**
 * The region's PCG asset library: game assets generated by PICG graphs.
 *
 * `content/pcg/index.json` (see @mmo-engine/picg library.ts) names each
 * asset — by the id spawn tables use, so entities find it through their
 * AssetRef hash — and the reusable parts graphs link. This class loads it,
 * prepares each asset's graph (linked parts inlined, parameters applied),
 * and cooks its shapes on demand through a PcgCooker (the native addon in
 * production): one mesh per (asset, variant index, revision), cooked once
 * and kept, concurrent requests sharing the cook.
 *
 * A revision counts changes to an asset (parameters now, the graph itself
 * later); a mesh is immutable per revision, so clients cache it forever.
 */

import { readFileSync } from "node:fs";
import * as path from "node:path";
import {
  exposedParameters,
  fnv1a32,
  parameterValues,
  parseLibraryIndex,
  prepareForCook,
  variantIndex,
  variantSeed,
  type PcgGraph,
  type PcgLibraryAsset,
  type PcgLibraryIndex,
  type PcgParameter,
} from "@mmo-engine/picg";

/** The native cook (packages/addons/picg), or a stand-in in tests. */
export interface PcgCooker {
  cook(graph: object, seed: number): Promise<
    { kind: "mesh"; mesh: ArrayBuffer; vertexCount: number; indexCount: number } | { kind: "json"; json: string } | { kind: "none" }
  >;
}

export interface PcgAssetInfo {
  id: string;
  assetHash: number;
  displayName: string;
  graph: string;
  variants: number;
  revision: number;
}

export interface CookedMesh {
  assetHash: number;
  variantIndex: number;
  revision: number;
  /** PCGM bytes (see @mmo-engine/picg decodePcgMesh). */
  bytes: Uint8Array;
  vertexCount: number;
  triangleCount: number;
}

interface Entry {
  asset: PcgLibraryAsset;
  info: PcgAssetInfo;
  /** The authoring graph as stored (linked parts unresolved). */
  graph: PcgGraph;
  /** Parameter values over the graph's defaults (from the index, then edits). */
  values: Record<string, unknown>;
  prepared: { revision: number; graph: object } | null;
}

export class PcgAssetLibrary {
  private readonly entries = new Map<number, Entry>();
  private readonly byId = new Map<string, Entry>();
  private readonly meshes = new Map<string, Promise<CookedMesh | null>>();

  private constructor(
    readonly root: string,
    private readonly index: PcgLibraryIndex,
    private readonly cooker: PcgCooker | null,
  ) {
    for (const asset of index.assets) {
      const graph = JSON.parse(readFileSync(this.file(asset.graph), "utf8")) as PcgGraph;
      const entry: Entry = {
        asset,
        graph,
        values: { ...(asset.parameters ?? {}) },
        prepared: null,
        info: {
          id: asset.id,
          assetHash: fnv1a32(asset.id),
          displayName: asset.displayName ?? graph.name ?? asset.id,
          graph: asset.graph,
          variants: Math.max(1, asset.variants ?? 1),
          revision: 1,
        },
      };
      if (this.entries.has(entry.info.assetHash)) throw new Error(`pcg library: asset hash collision on '${asset.id}'`);
      this.entries.set(entry.info.assetHash, entry);
      this.byId.set(asset.id, entry);
    }
  }

  /** Load `<root>/index.json`. Without a cooker, assets list but have no meshes. */
  static load(root: string, cooker: PcgCooker | null): PcgAssetLibrary {
    const index = parseLibraryIndex(JSON.parse(readFileSync(path.join(root, "index.json"), "utf8")));
    const library = new PcgAssetLibrary(path.resolve(root), index, cooker);
    // Fail at boot, not at the first request: every asset must prepare.
    for (const entry of library.entries.values()) library.prepared(entry);
    return library;
  }

  get canCook(): boolean {
    return this.cooker !== null;
  }

  list(): PcgAssetInfo[] {
    return [...this.entries.values()].map((e) => ({ ...e.info }));
  }

  info(assetHash: number): PcgAssetInfo | null {
    const e = this.entries.get(assetHash >>> 0);
    return e ? { ...e.info } : null;
  }

  infoById(id: string): PcgAssetInfo | null {
    const e = this.byId.get(id);
    return e ? { ...e.info } : null;
  }

  /** The authoring graph, its exposed parameters, and their current values. */
  detail(id: string): { info: PcgAssetInfo; graph: PcgGraph; parameters: PcgParameter[]; values: Record<string, unknown> } | null {
    const e = this.byId.get(id);
    if (!e) return null;
    return { info: { ...e.info }, graph: e.graph, parameters: exposedParameters(e.graph), values: parameterValues(e.graph, e.values) };
  }

  /**
   * The cooked shape an entity with this AssetRef shows (null: not a PCG
   * asset, or no cooker). Cooked once per revision; later calls share it.
   */
  mesh(assetHash: number, variant: number): Promise<CookedMesh | null> {
    const e = this.entries.get(assetHash >>> 0);
    if (!e || !this.cooker) return Promise.resolve(null);
    const vi = variantIndex(e.asset, variant);
    const revision = e.info.revision;
    const key = `${e.info.assetHash}:${vi}:${revision}`;
    let pending = this.meshes.get(key);
    if (!pending) {
      const cooker = this.cooker;
      pending = cooker.cook(this.prepared(e), variantSeed(e.asset, vi)).then((r) => {
        if (r.kind !== "mesh") return null;
        const bytes = new Uint8Array(r.mesh);
        return { assetHash: e.info.assetHash, variantIndex: vi, revision, bytes, vertexCount: r.vertexCount, triangleCount: Math.floor(r.indexCount / 3) };
      });
      // A failed cook isn't cached: the next request tries again.
      pending.catch(() => this.meshes.delete(key));
      this.meshes.set(key, pending);
    }
    return pending;
  }

  /** A mesh already cooked for exactly this revision (for GET by URL). */
  cachedMesh(assetHash: number, vi: number, revision: number): Promise<CookedMesh | null> | null {
    return this.meshes.get(`${assetHash >>> 0}:${vi}:${revision}`) ?? null;
  }

  /** Read a library file, refusing paths that leave the library. */
  private file(relative: string): string {
    const full = path.resolve(this.root ?? "", relative);
    const root = path.resolve(this.root ?? "");
    if (full !== root && !full.startsWith(root + path.sep)) throw new Error(`pcg library: '${relative}' is outside the library`);
    return full;
  }

  private prepared(e: Entry): object {
    if (e.prepared?.revision === e.info.revision) return e.prepared.graph;
    const files = new Map(this.index.subgraphs.map((s) => [s.guid, s.file]));
    const { graph } = prepareForCook(e.graph, {
      parameters: e.values,
      loadSubgraph: (guid) => {
        const file = files.get(guid);
        return file ? readFileSync(this.file(file), "utf8") : null;
      },
    });
    e.prepared = { revision: e.info.revision, graph };
    return graph;
  }
}
